import{_ as t,o as a,c as n,ak as o}from"./chunks/framework.B8jO0odJ.js";const p=JSON.parse('{"title":"Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","description":"!Chainy logo","frontmatter":{"title":"Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","description":"!Chainy logo","source":"README.md","category":"Start here","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/readme.md","filePath":"content/readme.md"}'),r={name:"content/readme.md"};function i(s,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai">Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)<a class="header-anchor" href="#chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai" aria-label="Link to this section">​</a></h1><p><img src="/Chainy-Docs/attachments/docs/media/brand/chainy-logo.png" alt="Chainy logo"></p><p>Chainy is a proposed offline Android exploration game for ages 12–17. Players complete 13 ordered lessons in each of Web3, Blockchain, and AI, collect encyclopedia entries, play three distinct minigames per world, and complete required quizzes to unlock the next world. Unity runs the game and SQLite stores local progress; there is no functioning economy.</p><p><strong>Current phase: documentation and preparation only. Unity development requires final owner approval.</strong><strong>Pre-final: November 21, 2026.</strong> The actual November 10 Cryptita Plays session outcome has not been established here.</p><p>This repository holds the team&#39;s decisions, documentation, and readiness plan. Start with the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a>, <a href="/Chainy-Docs/content/docs/planning/a-z-complete-lesson-quiz-source-draft.html">lesson source pack</a>, and <a href="/Chainy-Docs/content/docs/planning/lesson-collection-delivery.html">preparation workflow</a>. The <a href="/Chainy-Docs/content/docs/home.html">Obsidian second brain</a> maps the supporting documents; superseded designs remain recoverable.</p><h2 id="open-your-work">Open your work<a class="header-anchor" href="#open-your-work" aria-label="Link to this section">​</a></h2><table><thead><tr><th>I need to…</th><th>Open</th></tr></thead><tbody><tr><td>Understand the project</td><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Current decisions</a></td></tr><tr><td>Find my responsibilities and tasks</td><td><a href="/Chainy-Docs/content/docs/team-delegation.html">Team roles</a></td></tr><tr><td>Move task cards and edit the timeline</td><td><a href="https://owenlim225.github.io/Chainy-Docs/board/">Live team board</a> · <a href="/Chainy-Docs/content/docs/team-board-guide.html">Quick guide</a></td></tr><tr><td>Understand how the game plays</td><td><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Current game design</a></td></tr><tr><td>Build or review the systems</td><td><a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a></td></tr><tr><td>Find research, testing or supporting documents</td><td><a href="/Chainy-Docs/content/docs/documentation-index.html">Documentation index</a></td></tr><tr><td>Generate an optional image asset draft</td><td><a href="/Chainy-Docs/content/tools/fal/readme.html">fal API setup</a></td></tr></tbody></table><p>Use your individual account on the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a> to edit cards and dates. Changes are recorded by name and copied to the existing GitHub issues. Trello is disconnected; teammates do not need GitHub accounts.</p><p>Christian&#39;s supplied report lists several components in progress and the player controller completed. Those are <strong>tech-lead-reported component states</strong>, not independently tested whole-task completion. The old zero-progress statement is superseded.</p><p>The current game source is <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>. The November 7 local-source review has not established a candidate APK or a tested reference-device result; see the <a href="/Chainy-Docs/content/docs/project-baseline.html">current baseline</a>. Earlier specifications, internal notes and the previous illustrated PDF are <a href="/Chainy-Docs/content/docs/archive/readme.html">historical references</a>.</p></div>',1)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
